import ast, hashlib, importlib, json, os, resource, sys, textwrap
resource.setrlimit(resource.RLIMIT_AS,(512*1024*1024,512*1024*1024))
resource.setrlimit(resource.RLIMIT_CPU,(10,10))
sys.path.insert(0,os.getcwd())
op,target=sys.argv[1:]
tests=json.load(sys.stdin)
files={name:open(name,encoding="utf-8").read() for name in sorted(os.listdir()) if name.endswith(".py")}
defs={n.name:(f,n) for f,src in files.items() for n in ast.parse(src).body if isinstance(n,ast.FunctionDef)}

def first_difference(expected, actual, path=''):
    if isinstance(expected, dict):
        for key in expected:
            if expected[key] != actual[key]:
                return first_difference(expected[key], actual[key], path + '/' + key)
    elif isinstance(expected, list):
        if len(expected) != len(actual):
            return dict(path=path, aspect='length', expected=len(expected), actual=len(actual))
        for i, (a, b) in enumerate(zip(expected, actual)):
            if a != b:
                return first_difference(a, b, path + '/' + str(i))
    return dict(path=path, expected=expected, actual=actual)

if op=="apply":
    staged=dict(files)
    pending={}
    for edit in tests:
        f,n=defs[edit["function"]]
        pending.setdefault(f,[]).append((n.body[0].lineno-1,n.end_lineno,textwrap.indent(textwrap.dedent(edit['body']).strip(),'    ')+'\n'))
    for f,patches in pending.items():
        lines=files[f].splitlines(True)
        for start,end,body in sorted(patches,reverse=True):
            lines[start:end]=[body]
        staged[f]=''.join(lines)
        ast.parse(staged[f])
    print(json.dumps({f:staged[f] for f in pending}))
else:
    fn=getattr(importlib.import_module("panel"),target)
    if op=="run":
        print(json.dumps([fn(**item) for item in tests]))
    elif op in ("packet","diff","observed"):
        fail=next(((q,got) for q in tests if (got:=fn(**q["inputs"]))!=q["expect"]),None)
        if not fail: raise RuntimeError("expected a failing case")
        q,got=fail
        seen=[target]; definitions=[]
        extra={}
        payload=dict(inputs=q["inputs"])
        if op=="observed":
            seen=[]
            def on_call(frame,event,arg):
                if event=="call":
                    name=frame.f_code.co_name
                    if name in defs and os.path.basename(frame.f_code.co_filename)==defs[name][0] and name not in seen:
                        seen.append(name)
            sys.setprofile(on_call)
            try:
                replay=fn(**q["inputs"])
            finally:
                sys.setprofile(None)
            assert replay==got
            for name in seen:
                assert not any(isinstance(n,(ast.If,ast.IfExp,ast.BoolOp,ast.For,ast.While,ast.Try,ast.Match,ast.comprehension)) for n in ast.walk(defs[name][1]))
            extra=dict(execution=dict(complete=True,branches={}))
            if len('"inputs":'+json.dumps(q["inputs"],ensure_ascii=False,separators=(',',':')))>1024:
                payload=dict(input_example=q["name"])
        for name in seen:
            f,n=defs[name]
            for call in ast.walk(n):
                if op!="observed" and isinstance(call,ast.Call) and isinstance(call.func,ast.Name) and call.func.id in defs and call.func.id not in seen: seen.append(call.func.id)
            lines=files[f].splitlines()
            definitions.append(dict(node=f+":"+str(n.body[0].lineno)+":"+str(n.body[0].col_offset+1),signature=lines[n.lineno-1],body=textwrap.dedent('\n'.join(lines[n.body[0].lineno-1:n.end_lineno]))))
        types={}
        trees=[n for src in files.values() for n in ast.parse(src).body]
        decls={n.name:n for n in trees if isinstance(n,ast.ClassDef)}
        decls.update({n.targets[0].id:n for n in trees if isinstance(n,ast.Assign) and isinstance(n.targets[0],ast.Name)})
        def used_types(node):
            for ref in ast.walk(node):
                if isinstance(ref,ast.Name) and ref.id in decls and ref.id not in types:
                    decl=decls[ref.id]
                    types[ref.id]=ast.unparse(decl)
                    used_types(decl)
        for name in seen: used_types(defs[name][1])
        rev=hashlib.sha256(json.dumps([sorted(files.items()),tests],separators=(',',':')).encode()).hexdigest()
        print(json.dumps(dict(file="panel.py",code="E_EXAMPLE",message="Wrong output",example=q["name"],**(dict(difference=first_difference(q["expect"],got)) if op!="packet" and isinstance(got,(dict,list)) else dict(expected=q["expect"],actual=got)),repair=dict(revision=rev,entry="panel.py",target=target,**payload,**extra,types=types,definitions=definitions)),separators=(",",":")))
